package app.pulso.radio;
import android.Manifest;
import android.app.DownloadManager;
import android.content.*;
import android.net.Uri;
import android.os.*;
import androidx.core.content.ContextCompat;
import com.getcapacitor.*;
import com.getcapacitor.annotation.*;
@CapacitorPlugin(name="PulsoRadio",permissions={@Permission(alias="notifications",strings={Manifest.permission.POST_NOTIFICATIONS})})
public class PulsoRadioPlugin extends Plugin {
 private android.content.SharedPreferences prefs(){return getContext().getSharedPreferences("pulso_native",Context.MODE_PRIVATE);}
 private boolean save(PluginCall call){String code=call.getString("code",prefs().getString("code","")),secret=call.getString("secret",prefs().getString("secret",""));if(!code.matches("[1-9][0-9]{5}")||!secret.matches("[a-f0-9]{64}")){call.reject("Código de rádio inválido.");return false;}String session=call.getString("talkSession","");if(session.equals(prefs().getString("expiredTalkSession","")))session="";prefs().edit().putString("code",code).putString("secret",secret).putString("name",call.getString("name","Contato")).putString("contact",call.getString("contact","")).putString("callSound",call.getString("callSound","original")).putString("messageSound",call.getString("messageSound","ping")).putBoolean("directTone",call.getBoolean("directTone",false)).putString("hardwareButton",call.getString("hardwareButton","off")).putString("hardwareMode",call.getString("hardwareMode","talk")).putString("talkSession",session).putString("contactName",call.getString("contactName","")).putBoolean("beep",call.getBoolean("beep",true)).putLong("cursor",Math.max(prefs().getLong("cursor",0),call.getLong("cursor",0L))).apply();return true;}
 private JSObject state(){JSObject result=new JSObject();result.put("talkSession",prefs().getString("talkSession",""));result.put("running",RadioService.running);result.put("enabled",prefs().getBoolean("enabled",false));result.put("cursor",prefs().getLong("cursor",0));return result;}
 @PluginMethod public void start(PluginCall call){if(!save(call))return;if(call.getBoolean("askNotifications",true)&&Build.VERSION.SDK_INT>=33&&getPermissionState("notifications")!=PermissionState.GRANTED){requestPermissionForAlias("notifications",call,"afterNotifications");return;}begin(call);}
 @PermissionCallback private void afterNotifications(PluginCall call){begin(call);}
 private void begin(PluginCall call){try{prefs().edit().putBoolean("enabled",true).apply();ContextCompat.startForegroundService(getContext(),new Intent(getContext(),RadioService.class));JSObject response=state();response.put("running",true);response.put("notifications",Build.VERSION.SDK_INT<33||getPermissionState("notifications")==PermissionState.GRANTED);call.resolve(response);}catch(Exception e){call.reject("Não foi possível iniciar o rádio em segundo plano.",e);}}
 @PluginMethod public void importTone(PluginCall call){String kind=call.getString("kind","");String encoded=call.getString("audio","");if((!kind.equals("call")&&!kind.equals("message"))||encoded.length()>7000000){call.reject("Toque inválido ou muito grande.");return;}android.util.AtomicFile target=new android.util.AtomicFile(new java.io.File(getContext().getFilesDir(),"tone-"+kind+".audio"));java.io.FileOutputStream out=null;android.media.MediaPlayer probe=null;try{byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);if(bytes.length==0||bytes.length>5*1024*1024)throw new java.io.IOException();out=target.startWrite();out.write(bytes);out.getFD().sync();probe=new android.media.MediaPlayer();probe.setDataSource(target.getBaseFile().getAbsolutePath());probe.prepare();probe.release();probe=null;target.finishWrite(out);out=null;call.resolve();}catch(Exception error){if(out!=null)target.failWrite(out);call.reject("Não foi possível salvar este toque no Android.");}finally{if(probe!=null)probe.release();}}
 @PluginMethod public void configure(PluginCall call){if(!save(call))return;call.resolve(state());}
 @PluginMethod public void foreground(PluginCall call){RadioService.appVisible=call.getBoolean("visible",true);if(!RadioService.appVisible){Long cursor=call.getLong("cursor",null);if(cursor!=null)prefs().edit().putLong("cursor",Math.max(cursor,prefs().getLong("cursor",0))).apply();}JSObject result=state();if(RadioService.appVisible){try{result.put("backlog",new JSArray(prefs().getString("backlog","[]")));prefs().edit().putString("backlog","[]").apply();}catch(Exception ignored){}}call.resolve(result);}
 @PluginMethod public void fullscreen(PluginCall call){boolean enabled=call.getBoolean("enabled",true);getActivity().runOnUiThread(()->{try{((MainActivity)getActivity()).applyFullscreen(enabled);prefs().edit().putBoolean("fullscreen",enabled).apply();call.resolve();}catch(Exception error){call.reject("Não foi possível ajustar tela cheia.");}});}
 @PluginMethod public void status(PluginCall call){call.resolve(state());}
 @PluginMethod public void stop(PluginCall call){prefs().edit().putBoolean("enabled",false).apply();getContext().stopService(new Intent(getContext(),RadioService.class));call.resolve(state());}
 @PluginMethod public void batterySettings(PluginCall call){try{getActivity().startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getContext().getPackageName())));call.resolve();}catch(Exception e){call.reject("Abra os ajustes do app no Android.");}}
 @PluginMethod public void download(PluginCall call){String id=call.getString("id","");if(!id.matches("[a-f0-9-]{36}")){call.reject("Arquivo inválido.");return;}try{String filename=call.getString("name","arquivo").replaceAll("[\\\\/:*?\"<>|]","_");DownloadManager.Request request=new DownloadManager.Request(Uri.parse("https://pulso-radio-matheus.airycake256.chatgpt.site/api/radio/download?id="+id));request.addRequestHeader("Authorization","Bearer "+prefs().getString("code","")+"."+prefs().getString("secret",""));request.setTitle(filename);request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,filename);long downloadId=((DownloadManager)getContext().getSystemService(Context.DOWNLOAD_SERVICE)).enqueue(request);JSObject result=new JSObject();result.put("downloadId",downloadId);call.resolve(result);}catch(Exception e){call.reject("Não foi possível salvar o arquivo.",e);}}
}
